3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerTelephoneException;
6	
7	/**
8	 * Normalizes the create-owner telephone: strips every non-digit character and requires
9	 * exactly ten digits. Mutates the published request in place so later steps store and
10	 * return the 10-digit value. Rejects anything that is not exactly ten digits with a 400.
11	 */
12	public class NormalizeOwnerTelephone {
13	
14	    public void service(@Val OwnerFieldsDto request) throws InvalidOwnerTelephoneException {
15	        String telephone = request.getTelephone();
16	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
17	        if (digits.length() != 10) {
18	            throw new InvalidOwnerTelephoneException(telephone);
19	        }
20	        request.setTelephone(digits);
21	    }
22	}
