3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerTelephoneException;
8	
9	/**
10	 * Rejects a create-owner request whose normalized telephone is already used by another
11	 * owner with a 409. Runs after {@code NormalizeOwnerTelephone}, so the request telephone
12	 * is already the 10-digit form; each existing owner's telephone is normalized the same
13	 * way (non-digits stripped) before comparison.
14	 */
15	public class CheckOwnerTelephoneUnique {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateOwnerTelephoneException {
19	        String telephone = normalize(request.getTelephone());
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (telephone.equals(normalize(existing.getTelephone()))) {
22	                throw new DuplicateOwnerTelephoneException(request.getTelephone());
23	            }
24	        }
25	    }
26	
27	    private static String normalize(String telephone) {
28	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
29	    }
30	}
